import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .pred %p<4>;
    .reg .u32 %r<40>;
    .reg .u64 %rd<20>;
    .reg .f32 %f<10>;

    .shared .align 4 .b8 As[4096];
    .shared .align 4 .b8 Bs[4096];

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [N];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %tid.y;
    mov.u32 %r4, %ctaid.x;
    mov.u32 %r5, %ctaid.y;

    mad.lo.u32 %r6, %r5, 32, %r3;   // row = ctaid.y*32 + tid.y
    mad.lo.u32 %r7, %r4, 32, %r2;   // col = ctaid.x*32 + tid.x

    setp.ge.u32 %p1, %r6, %r1;
    setp.ge.u32 %p2, %r7, %r1;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    shr.u32 %r8, %r1, 5;           // ntiles = N / 32

    mov.f32 %f1, 0f00000000;       // sum = 0.0f

    mov.u32 %r9, 0;                // t = 0

    mad.lo.u32 %r10, %r3, 32, %r2; // ty*32 + tx
    shl.b32 %r11, %r10, 2;         // byte offset
    mov.u32 %r12, As;
    add.u32 %r13, %r12, %r11;      // &As[ty][tx]
    mov.u32 %r14, Bs;
    add.u32 %r15, %r14, %r11;      // &Bs[ty][tx]

LOOP_START:
    setp.ge.u32 %p1, %r9, %r8;
    @%p1 bra LOOP_END;

    mad.lo.u32 %r16, %r9, 32, %r2;   // a_col = t*32 + tx
    mad.lo.u32 %r17, %r6, %r1, %r16; // a_flat = row*N + a_col
    mul.wide.u32 %rd4, %r17, 4;
    add.s64 %rd5, %rd1, %rd4;
    ld.global.f32 %f2, [%rd5];
    st.shared.f32 [%r13], %f2;

    mad.lo.u32 %r18, %r9, 32, %r3;   // b_row = t*32 + ty
    mad.lo.u32 %r19, %r18, %r1, %r7; // b_flat = b_row*N + col
    mul.wide.u32 %rd6, %r19, 4;
    add.s64 %rd7, %rd2, %rd6;
    ld.global.f32 %f3, [%rd7];
    st.shared.f32 [%r15], %f3;

    bar.sync 0;

    mov.u32 %r20, 0;
INNER_LOOP:
    setp.ge.u32 %p1, %r20, 32;
    @%p1 bra INNER_END;

    mad.lo.u32 %r21, %r3, 32, %r20;  // As[ty][k]
    shl.b32 %r22, %r21, 2;
    mov.u32 %r23, As;
    add.u32 %r24, %r23, %r22;
    ld.shared.f32 %f4, [%r24];

    mad.lo.u32 %r25, %r20, 32, %r2;  // Bs[k][tx]
    shl.b32 %r26, %r25, 2;
    mov.u32 %r27, Bs;
    add.u32 %r28, %r27, %r26;
    ld.shared.f32 %f5, [%r28];

    fma.rn.f32 %f1, %f4, %f5, %f1;

    add.u32 %r20, %r20, 1;
    bra INNER_LOOP;
INNER_END:

    bar.sync 0;

    add.u32 %r9, %r9, 1;
    bra LOOP_START;
LOOP_END:

    mad.lo.u32 %r30, %r6, %r1, %r7;  // c_flat = row*N + col
    mul.wide.u32 %rd8, %r30, 4;
    add.s64 %rd9, %rd3, %rd8;
    st.global.f32 [%rd9], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom PTX kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.shape == B.shape
        assert A.dim() == 2 and A.shape[0] == A.shape[1]

        N = A.shape[0]

        A = A.contiguous()
        B = B.contiguous()

        C = torch.empty((N, N), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block = (32, 32, 1)
        grid = (N // 32, N // 32, 1)

        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

